#!/usr/bin/env bash
# Builds a Rust core of @CONTRACT@ for the target platforms and lays the
# libraries out the way the generated packages expect them (generated by
# wabi-wit-gen — DO NOT EDIT):
#
#   <out>/linux-x64/lib@LIB@.so           <out>/linux-arm64/lib@LIB@.so
#   <out>/windows-x64/@LIB@.dll
#   <out>/macos/lib@LIB@.dylib            (universal arm64 + x86_64)
#   <out>/ios/lib@LIB@.dylib              <out>/ios-simulator/lib@LIB@.dylib (arm64 + x86_64)
#   <out>/apple/@XCF@.xcframework         (static, for Swift/Xcode: iOS device + simulator + macOS)
#   <out>/android/jniLibs/<abi>/lib@LIB@.so   (arm64-v8a armeabi-v7a x86_64 x86)
#
# The Dart package (hook/build.dart, Flutter) and the NuGet package pick them up
# from <out> without further configuration.
#
#   build-native.sh <core crate dir> [host|linux-x64|linux-arm64|windows-x64|macos|ios|android|all ...]
#
#   <out>   default: ../native next to this script; override with OUT=<dir>
#   needs   rustup; cross targets: zig (linux-arm64, windows-x64 from Linux/macOS),
#           macOS + Xcode (macos, ios), cargo-ndk + ANDROID_NDK_HOME (android)
#
# The crate must be named so that it produces lib@LIB@: [lib] name = "@LIB@",
# crate-type = ["cdylib", "staticlib"]. Missing toolchains are reported and skipped.
set -euo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"
CORE="$(cd "${1:?usage: build-native.sh <core crate dir> [targets...]}" && pwd)"
shift
OUT="${OUT:-$HERE/../native}"
mkdir -p "$OUT" && OUT="$(cd "$OUT" && pwd)"
TGT="${CARGO_TARGET_DIR:-$CORE/target}"
LIB=@LIB@
HEADERS="$HERE/../abi/wabi_abi.h $HERE/../abi/wabi_abi_functions.h $HERE/../c/@LIB@.h"
have() { command -v "$1" >/dev/null 2>&1; }
skip() { echo "SKIP $1: $2"; }
cargo_build() { rustup target add "$1" >/dev/null 2>&1 || true; (cd "$CORE" && cargo build --release --lib --target "$1" "${@:2}"); }

# zig as C cross compiler and linker (written next to the build, no install step)
ZIGCC="$TGT/zig-cc.sh"
zig_ready() {
  have zig || python3 -c "import ziglang" 2>/dev/null || return 1
  mkdir -p "$TGT"
  cat > "$ZIGCC" <<'ZIG'
#!/usr/bin/env bash
if command -v zig >/dev/null 2>&1; then Z=(zig); else Z=(python3 -m ziglang); fi
args=()
for a in "$@"; do
  case "$a" in
    --target=*|-Wl,--as-needed|-Wl,-Bdynamic|-Wl,-Bstatic|-Wl,--fix-cortex-a53-843419) ;; # rustc flags zig rejects
    -Wl,*.def) args+=("${a#-Wl,}") ;;                    # windows-gnu: export list as an input file
    -lgcc_eh) args+=(-lunwind) ;;                        # unwinding: zig's libunwind
    -l:libpthread.a|-lgcc|-lmsvcrt|-lmingwex|-lmingw32) ;; # mingw runtime: zig links its own
    *) args+=("$a") ;;
  esac
done
exec "${Z[@]}" cc -target "${ZIG_TARGET:?}" "${args[@]}"
ZIG
  chmod +x "$ZIGCC"
}

host_target() {
  case "$(uname -s)-$(uname -m)" in
    Linux-x86_64) echo linux-x64 ;;
    Linux-aarch64|Linux-arm64) echo linux-arm64 ;;
    Darwin-*) echo macos ;;
    MINGW*|MSYS*|CYGWIN*) echo windows-x64 ;;
    *) echo "unknown host $(uname -s)-$(uname -m)" >&2; exit 2 ;;
  esac
}

build_linux() { # dir rust-target zig-target
  local dir=$1 t=$2
  if [[ "$(host_target)" == "$dir" ]]; then cargo_build "$t"
  elif zig_ready; then
    local up; up=$(echo "$t" | tr 'a-z-' 'A-Z_')
    (export ZIG_TARGET="$3" "CARGO_TARGET_${up}_LINKER=$ZIGCC" "CC_${t//-/_}=$ZIGCC"; cargo_build "$t")
  else skip "$dir" "needs zig (pip install ziglang) to cross-compile"; return; fi
  mkdir -p "$OUT/$dir" && cp "$TGT/$t/release/lib$LIB.so" "$OUT/$dir/"
}

build_windows() {
  if [[ "${OS:-}" == "Windows_NT" ]]; then
    cargo_build x86_64-pc-windows-msvc
    mkdir -p "$OUT/windows-x64" && cp "$TGT/x86_64-pc-windows-msvc/release/$LIB.dll" "$OUT/windows-x64/"
  elif zig_ready; then
    (export ZIG_TARGET=x86_64-windows-gnu CARGO_TARGET_X86_64_PC_WINDOWS_GNU_LINKER="$ZIGCC" CC_x86_64_pc_windows_gnu="$ZIGCC"
      cargo_build x86_64-pc-windows-gnu)
    mkdir -p "$OUT/windows-x64" && cp "$TGT/x86_64-pc-windows-gnu/release/$LIB.dll" "$OUT/windows-x64/"
  else skip windows-x64 "needs Windows (MSVC) or zig"; fi
}

build_macos() {
  if [[ "$(uname -s)" != Darwin ]]; then skip macos "needs macOS"; return; fi
  for t in aarch64-apple-darwin x86_64-apple-darwin; do cargo_build "$t"; done
  mkdir -p "$OUT/macos"
  lipo -create "$TGT"/{aarch64,x86_64}-apple-darwin/release/lib$LIB.dylib -output "$OUT/macos/lib$LIB.dylib"
  install_name_tool -id "@rpath/lib$LIB.dylib" "$OUT/macos/lib$LIB.dylib"
}

build_ios() {
  if [[ "$(uname -s)" != Darwin ]] || ! have xcodebuild; then skip ios "needs macOS + Xcode"; return; fi
  for t in aarch64-apple-ios aarch64-apple-ios-sim x86_64-apple-ios aarch64-apple-darwin x86_64-apple-darwin; do cargo_build "$t"; done
  local W="$TGT/wabi-apple"; rm -rf "$W"; mkdir -p "$W/include" "$OUT/ios" "$OUT/ios-simulator" "$OUT/apple"
  # Dart native assets (Flutter): one dynamic library per platform
  cp "$TGT/aarch64-apple-ios/release/lib$LIB.dylib" "$OUT/ios/"
  lipo -create "$TGT"/{aarch64-apple-ios-sim,x86_64-apple-ios}/release/lib$LIB.dylib -output "$OUT/ios-simulator/lib$LIB.dylib"
  for d in ios ios-simulator; do install_name_tool -id "@rpath/lib$LIB.dylib" "$OUT/$d/lib$LIB.dylib"; done
  # Swift/Xcode: static xcframework with the C module C@XCF@
  lipo -create "$TGT"/{aarch64-apple-ios-sim,x86_64-apple-ios}/release/lib$LIB.a -output "$W/sim.a"
  lipo -create "$TGT"/{aarch64,x86_64}-apple-darwin/release/lib$LIB.a -output "$W/macos.a"
  cp $HEADERS "$W/include/"
  printf 'module C@XCF@ {\n    header "wabi_abi.h"\n    header "@LIB@.h"\n    export *\n}\n' > "$W/include/module.modulemap"
  rm -rf "$OUT/apple/@XCF@.xcframework"
  xcodebuild -create-xcframework \
    -library "$TGT/aarch64-apple-ios/release/lib$LIB.a" -headers "$W/include" \
    -library "$W/sim.a" -headers "$W/include" \
    -library "$W/macos.a" -headers "$W/include" \
    -output "$OUT/apple/@XCF@.xcframework"
  rm -rf "$W"
}

build_android() {
  if ! have cargo-ndk || [[ -z "${ANDROID_NDK_HOME:-}" ]]; then skip android "needs cargo-ndk (cargo install cargo-ndk) + ANDROID_NDK_HOME"; return; fi
  rustup target add aarch64-linux-android armv7-linux-androideabi x86_64-linux-android i686-linux-android >/dev/null
  (cd "$CORE" && cargo ndk -t arm64-v8a -t armeabi-v7a -t x86_64 -t x86 -o "$OUT/android/jniLibs" build --release --lib)
}

build() {
  case "$1" in
    host) build "$(host_target)" ;;
    linux-x64) build_linux linux-x64 x86_64-unknown-linux-gnu x86_64-linux-gnu.2.28 ;;
    linux-arm64) build_linux linux-arm64 aarch64-unknown-linux-gnu aarch64-linux-gnu.2.28 ;;
    windows-x64) build_windows ;;
    macos) build_macos ;;
    ios) build_ios ;;
    android) build_android ;;
    all) for t in linux-x64 linux-arm64 windows-x64 macos ios android; do build "$t"; done ;;
    *) echo "unknown target $1 (host linux-x64 linux-arm64 windows-x64 macos ios android all)" >&2; exit 2 ;;
  esac
}
[ $# -gt 0 ] || set -- host
for t in "$@"; do build "$t"; done
echo "libraries in $OUT:"
(cd "$OUT" && find . \( -name '*.so' -o -name '*.dll' -o -name '*.dylib' -o -name '*.xcframework' -prune \) -print | sort)
